-- Migration 20261025192217_appearance_person_fk: generated by drizzle-kit, hand-reviewed before commit.
-- Reviewed-by: Claude (agent, #357)
-- Tenancy hole (#357, ADR 0013): appearance.appearing_for_person_id (0041) never got its FK to person, so a row
-- could name another workspace's person. Adds appearance_appearing_for_person_fk as a composite
-- (workspace_id, appearing_for_person_id) -> person(workspace_id, id) FK, ON DELETE SET NULL (appearing_for_person_id).
-- Hand edit: drizzle-kit emits a plain `ON DELETE set null`, which would also null the NOT NULL workspace_id; the
-- column list (as on appearance_member_fk) clears only the person column.
-- Existing rows: the constraint is not added NOT VALID: validation would fail
-- on a bad row. Instead, before adding it, every appearing_for_person_id that does not match a person in the
-- same workspace is nulled (a dangling or cross-workspace reference carries no usable meaning, and nulling matches
-- the SET NULL delete action). causedeck_owner is bound by FORCE RLS and sees no rows without app.workspace_id, so
-- the cleanup runs once per workspace (organization is not tenant-scoped) with the setting set transaction-locally,
-- then cleared. Valid references are untouched.
DO $$
DECLARE
	ws uuid;
BEGIN
	FOR ws IN SELECT "id" FROM "organization" LOOP
		PERFORM set_config('app.workspace_id', ws::text, true);
		UPDATE "appearance" a SET "appearing_for_person_id" = NULL
		WHERE a."appearing_for_person_id" IS NOT NULL
			AND NOT EXISTS (
				SELECT 1 FROM "person" p
				WHERE p."workspace_id" = a."workspace_id" AND p."id" = a."appearing_for_person_id"
			);
	END LOOP;
	PERFORM set_config('app.workspace_id', '', true);
END
$$;--> statement-breakpoint
ALTER TABLE "appearance" ADD CONSTRAINT "appearance_appearing_for_person_fk" FOREIGN KEY ("workspace_id","appearing_for_person_id") REFERENCES "public"."person"("workspace_id","id") ON DELETE SET NULL ("appearing_for_person_id") ON UPDATE no action;
